function finite(name, x) {
  const n = Number(x);
  if (!Number.isFinite(n)) throw new Error(`Invalid value for ${name}: ${x}.`);
  return n;
}

export const metres = (x) => finite('metres', x);
export const kilograms = (x) => finite('kilograms', x);
export const seconds = (x) => finite('seconds', x);
export const litres = (x) => finite('litres', x);
export const kelvin = (x) => finite('kelvin', x);
